pub mod pixels;pub mod linear;pub mod geometry;pub mod warp;
fn main(){let args:Vec<_>=std::env::args().collect();let family=&args[1];let radius:u32=args[2].parse().unwrap();let mut values=Vec::new();for y in 0..48 {for x in 0..48 {let r=((x*17+y*31)%127) as f32/63.-0.2;let g=if family=="gray"{r}else{((x*23+y*13)%113) as f32/67.};let b=if family=="gray"{r}else{((x*37+y*7)%109) as f32/71.};values.extend([r,g,b,if (x+y)%7==0{0.5}else{1.}]);}}let view=linear::LinearRgbaView::new(48,48,&values,2304,||false).unwrap();let initial=geometry::ProjectiveTransform{matrix:[[1.,0.,0.3],[0.,1.,-0.2],[0.,0.,1.]]};let policy=warp::ProjectiveRegistrationPolicy{radius,stride:4,rounds:12,max_sample_pairs:10000000};let calls=std::cell::Cell::new(0u64);let start=std::time::Instant::now();let model=warp::refine_projective_pixels(&view,&view,initial,policy,||{calls.set(calls.get()+1);false}).unwrap();let nanos=start.elapsed().as_nanos();println!("{} {} {:?}",nanos,calls.get(),model.matrix.map(|r|r.map(f64::to_bits)));}
